#include <cmath>
#include <algorithm> // For std::clamp

// --- Controller State ---
// These must be global or class members to persist between loop iterations
double prev_w_d = 0; 
double prev_v_d = 0; 
double integral_v = 0; // Accumulator for linear velocity error
double integral_w = 0; // Accumulator for angular velocity error
const double DT = 0.02; // Loop time in seconds

// --- Feedforward Gains ---
const float kV = 0.0536081766093; 
const float KA_turn = 0.00186762266749;
const float KA_straight = 0.00318573203587;
const float KS_turn = 0.590215565608;
const float KS_straight = 0.355059053395;

// --- Feedback Gains ---
const float KP_straight = 0.109602958174;
const float KI_straight = 1.98706406926;
const float KP_turn = 0.0634928503766;
const float KI_turn = 1.1537283158;


float sgn(float val) {
    if (val > 0) return 1.0f;
    if (val < 0) return -1.0f;
    return 0.0f;
}

struct Voltages {
    float left;
    float right;
};



Voltages voltageController(double v_d, double w_d, double track_width,
                           double v_actual_left_mps, double v_actual_right_mps) 
{
    float v_desired = (float)v_d;
    float w_desired = (float)w_d;
    float prev_w_desired = (float)prev_w_d;
    float prev_v_desired = (float)prev_v_d;
    
    float deltaW = (w_desired - prev_w_desired) / DT;
    prev_w_d = w_desired; 

    float deltaV = (v_desired - prev_v_desired) / DT;
    prev_v_d = v_desired; 

    float v_left_target = v_desired - w_desired * ((float)track_width / 2.0f);
    float v_right_target = v_desired + w_desired * ((float)track_width / 2.0f);
    float accel_left = (KA_straight * deltaV) - (KA_turn * deltaW);             
    float friction_left = (KS_straight * sgn(v_left_target)) - (KS_turn * sgn(w_desired)); 
    float ff_left = (kV * v_left_target) + accel_left + friction_left;

    float accel_right = (KA_straight * deltaV) + (KA_turn * deltaW);               
    float friction_right = (KS_straight * sgn(v_right_target)) + (KS_turn * sgn(w_desired)); 
    float ff_right = (kV * v_right_target) + accel_right + friction_right;

    // === 2. FEEDBACK (FB) CALCULATIONS ===
    float v_actual = ((float)v_actual_right_mps + (float)v_actual_left_mps) / 2.0f;
    float w_actual = ((float)v_actual_right_mps - (float)v_actual_left_mps) / (float)track_width;

    float v_error = v_desired - v_actual;
    float w_error = w_desired - w_actual;
    integral_v += v_error * DT;
    integral_w += w_error * DT;

    float fb_linear = (KP_straight * v_error) + (KI_straight * integral_v);
    float fb_angular = (KP_turn * w_error) + (KI_turn * integral_w);

    float output_left = std::clamp(ff_left + fb_linear - fb_angular, -12.0f, 12.0f);
    float output_right = std::clamp(ff_right + fb_linear + fb_angular, -12.0f, 12.0f);

    return {output_left, output_right};
}


// Wrap angle difference into range [-pi, pi)
double angleError(double robotAngle, double targetAngle) {
    constexpr double TWO_PI = 2.0 * M_PI;

    double diff = std::fmod(targetAngle - robotAngle, TWO_PI);

    if (diff < -M_PI) {
        diff += TWO_PI;
    } else if (diff >= M_PI) {
        diff -= TWO_PI;
    }

    return diff;
}


const double wheel_circumference = 4 * M_PI * INCH_TO_METER; // meters
const double gear_ratio = 0.8;
const double rps_to_mps_factor = (wheel_circumference / gear_ratio) / 60;

inline double sinc(double x) {
    const double eps = 1e-9;
    if (std::abs(x) < eps) {
        // 1 - x^2/6 + O(x^4)
        return 1.0 - (x * x) / 6.0;
    }
    return std::sin(x) / x;
}

void ramsete_auton() {
    const double b = 20;     
    const double zeta = 0.5; 
    const double track_width = 10.05 * INCH_TO_METER;
    VelocityProfile vp;

    std::vector<State> trajectory = prepare_trajectory();
    if (trajectory.empty())
        return;

    chassis.setPose(trajectory[0].x / INCH_TO_METER, trajectory[0].y / INCH_TO_METER, trajectory[0].heading, true);
    std::vector<std::string> logs;
    
    double start_time_ms = pros::millis();

    for (const auto &target_state : trajectory) {
        // Record the start time of this specific loop iteration
        uint32_t loop_start_time_ms = pros::millis();

        lemlib::Pose current_pose = chassis.getPose(true);
        Eigen::Matrix3d rotation_matrix;
        Eigen::Vector3d global_error;
        Eigen::Vector3d local_error;

        current_pose.x *= INCH_TO_METER;
        current_pose.y *= INCH_TO_METER;
        current_pose.theta = M_PI_2 - current_pose.theta;
        double AngleError = angleError(current_pose.theta, target_state.heading); 

        rotation_matrix << std::cos(current_pose.theta), std::sin(current_pose.theta), 0, -std::sin(current_pose.theta),
            std::cos(current_pose.theta), 0, 0, 0, 1;

        global_error << target_state.x - current_pose.x, target_state.y - current_pose.y,
            AngleError;

        local_error = rotation_matrix * global_error;

        double vd = target_state.linear_vel;
        double wd = target_state.angular_vel;
        double e_x = local_error(0);
        double e_y = local_error(1);
        double e_t = local_error(2);

        double k = 2.0 * zeta * std::sqrt(wd * wd + b * vd * vd);
        double v_desired_ramsete = vd * std::cos(e_t) + k * e_x;
        double w_desired_ramsete = wd + k * e_t + (b * vd * sinc(e_t) * e_y);

        Voltages output_voltages = voltageController(vd, wd, track_width, leftMotors.get_actual_velocity() * rps_to_mps_factor,rightMotors.get_actual_velocity() * rps_to_mps_factor);
       
        rightMotors.move_voltage(output_voltages.right * 1000.0);
        leftMotors.move_voltage(output_voltages.left * 1000.0);
        
        
        double time_sec = (pros::millis() - start_time_ms) / 1000.0;

        std::ostringstream ss;
        ss << Vector2(time_sec, leftMotors.get_actual_velocity()).latex() << ",";
        logs.push_back(ss.str());


        uint32_t processing_time_ms = pros::millis() - loop_start_time_ms;
        int remaining_delay_ms = 20 - processing_time_ms;
        if (remaining_delay_ms > 0) {
            pros::delay(remaining_delay_ms);
        }
    }

    rightMotors.brake();
    leftMotors.brake();

    for (const auto& line : logs) {
        std::cout << line;
        pros::delay(100);
    }
}


